<span class="line"><span style="color:#ABB2BF;">X </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> d2l.</span><span style="color:#61AFEF;">ones</span><span style="color:#ABB2BF;">((batch_size, num_queries, num_hiddens))</span></span>
